function createRequirements(remaining,major,school){
 let left=remaining;const courses=[];
 for(const[code,name,rawCredits,pre]of CURRICULA[major]){const credits=school==='GCSU'&&major==='ME'&&code==='MATH 2401'?3:rawCredits;if(left>=credits){courses.push({code,name,credits,pre:[...pre],kind:'Major core'});left-=credits;}}
 let i=1;while(left>0){const credits=Math.min(3,left);courses.push({code:`${school} ELEC ${String(i++).padStart(2,'0')}`,name:credits===3?'Degree requirement / approved elective':'Remaining degree requirement',credits,pre:[],kind:'Degree elective'});left-=credits;}
 return courses;
}
function schedule(a,major,school,load,summer,cleared){
 let pending=createRequirements(a.remaining,major,school),done=new Set(),year=2026,season='Fall',out=[],guard=0;
 while(pending.length&&guard++<100){
  const isSummer=season==='Summer',cap=isSummer?6:load;
  if(!isSummer||summer){
   let planned=[];
   if(a.delay&&!cleared&&out.length===0)planned=[{code:'PREREQ REVIEW',name:'Statics gap clearance / blocked engineering sequence',credits:0,pre:[],kind:'Delay term'}];
   else{let space=cap;for(const c of pending.filter(c=>c.pre.every(p=>done.has(p))))if(c.credits<=space){planned.push(c);space-=c.credits;}const selected=new Set(planned.map(c=>c.code));pending=pending.filter(c=>!selected.has(c.code));}
   out.push({term:`${season} ${year}`,season,year,courses:planned,credits:planned.reduce((n,c)=>n+c.credits,0),capacity:cap,delay:a.delay&&!cleared&&out.length===0});planned.forEach(c=>done.add(c.code));
  }
  if(season==='Fall'){season='Spring';year++;}else if(season==='Spring')season='Summer';else season='Fall';
 }
 return out;
}
const termIndex=t=>t?t.year*2+(t.season==='Fall'?1:t.season==='Summer'?.5:0):0;
function scenario(courses,school,major,load,summer,cleared,appeals={}){
 const a=audit(courses,school,major,appeals),u=UNIVERSITIES[school],roadmap=schedule(a,major,school,load,summer,cleared);
 const blind={...a,remaining:Math.max(0,a.total-Math.max(0,a.accepted-9))},baseline=schedule(blind,major,school,12,false,false);
 const standard=schedule(a,major,school,16,false,false);
 const ideal=schedule({...a,remaining:Math.max(0,a.total-a.completed),delay:false},major,school,16,false,true);
 const cost=plan=>plan.reduce((sum,t)=>sum+(t.season==='Summer'?t.credits*u.tuition/15:u.tuition),0),prep=a.delay&&cleared?200:0;
 const regular=roadmap.filter(t=>t.season!=='Summer').length,semestersSaved=baseline.filter(t=>t.season!=='Summer').length-regular;
 const improvement=Math.max(0,standard.filter(t=>t.season!=='Summer').length-regular);
 const delayTerms=Math.max(0,Math.ceil(termIndex(roadmap.at(-1))-termIndex(ideal.at(-1))));
 const boost=improvement+(summer?.7:0)+Math.max(0,load-16)*.45+(cleared&&a.delay?.7:0)+(appeals[school]?.7:0);
 const pressure=Math.max(0,a.loss/a.completed*2+(a.delay&&!cleared?.65:0)-boost);
 const caught=pressure>=.9&&delayTerms>0;
 const safe=pressure<.2, risk=caught?'CRITICAL BREACH':pressure>=.3?'MODERATE':'LOW RISK';
 return{...a,roadmap,baseline,ideal,graduation:roadmap.at(-1)?.term||'Already complete',cost:cost(roadmap)+prep,baselineCost:cost(baseline),saved:Math.round(cost(baseline)-cost(roadmap)-prep),semestersSaved,regular,summers:roadmap.filter(t=>t.season==='Summer').length,improvement,delayTerms,boost,pressure,caught,safe,risk};
}

